insert into missions (id, sponsor_id, title, area, plan, points, prize, description, joined_count, delivered_count, days_left) values
('m1', 'litoralpay', 'Troco solidário', 'App', 'patrocinador', 300, 'Bolsa de R$ 1.000 + mentoria com o time de produto', 'Crie o protótipo de um app que arredonda o valor de uma compra e doa a diferença para uma ONG de Santa Catarina. Mostre o fluxo em 3 telas.', 1420, 380, 18),
('m2', 'blusoft', 'Chatbot do suporte', 'IA', 'parceiro', 450, 'Semana de experiência na Blusoft + entrevista para estágio', 'Monte um chatbot que responde às 10 dúvidas mais comuns dos clientes de um sistema de gestão. Pode usar regras ou IA.', 2110, 540, 25),
('m3', 'joinvix', 'Manutenção preditiva', 'IoT', 'patrocinador', 300, 'Visita técnica à fábrica + kit Arduino', 'Use sensores simulados de vibração e temperatura para avisar quando um motor precisa de manutenção.', 960, 210, 20),
('m4', 'portox', 'Porto Rush', 'Games', 'apoiador', 200, 'Troféu Tech SC + visita guiada ao porto', 'Crie um jogo curto em que o jogador organiza contêineres e navios no menor tempo possível.', 1280, 330, 12),
('m5', 'fiosul', 'Vitrine de moda sustentável', 'Design', 'apoiador', 200, 'Mentoria de design + peças da coleção', 'Desenhe a página inicial de uma loja que mostra a origem e o impacto de cada peça.', 740, 170, 15),
('m6', 'colmeia', 'Painel de desperdício', 'Dados', 'apoiador', 200, 'Curso de análise de dados + almoço com o time', 'Transforme uma planilha de sobras da cozinha em um painel que aponta onde há mais desperdício.', 650, 120, 22),
('m7', 'enervale', 'Calculadora solar', 'App', 'parceiro', 450, 'Estágio de férias + kit solar didático', 'Faça uma calculadora que estima a economia na conta de luz com energia solar em casas catarinenses.', 1520, 290, 28);
